import java.util.LinkedList;
import java.util.Queue;

public class BinaryTree {
    private class Node {
        private Node left;
        private Node right;
        private int value;

        public Node(int value) {
            this.value = value;
        }
    }

    private Node root;

    public BinaryTree(int value) {
        root = new Node(value);
    }

    public void levelOrder() {
        if (root == null) {
            return;
        }
        Queue<Node> queue = new LinkedList<>();
        queue.add(root);
        while (!queue.isEmpty()) {
            Node node = queue.remove();
            if (node.left != null) {
                queue.add(node.left);
            }
            if (node.right != null) {
                queue.add(node.right);
            }
            System.out.println(node.value);
        }
    }
}

import java.util.ArrayList;
import java.util.LinkedList;
import java.util.Queue;

public class BFSGraph {

    private Graph graph;
    private boolean[] visited;
    private ArrayList<Integer> order;

    public BFSGraph(Graph graph) {
        this.graph = graph;
        visited = new boolean[graph.V()];
        order = new ArrayList<>(graph.V());

        for (int i = 0; i < graph.V(); i++) {
            if (!visited[i]) {
                bfs(i);
            }
        }
    }

    private void bfs(int s) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(s);
        visited[s] = true;
        while (!queue.isEmpty()) {
            int v = queue.remove();
            order.add(v);
            for (int w: graph.adj(v)) {
                if (!visited[w]) {
                    queue.add(w);
                    visited[w] = true;
                }
            }
        }
    }

    public static void main(String[] args) {
        Graph graph = new AdjSet("g4.txt");
        BFSGraph bfsGraph = new BFSGraph(graph);
        System.out.println(bfsGraph.order);
    }
}

import java.util.*;

public class SingleSourcePath {
    private Graph graph;
    private int s;

    private boolean[] visited;
    private int[] pre;

    public SingleSourcePath(Graph graph, int s) {
        this.graph = graph;
        this.s = s;

        visited = new boolean[graph.V()];
        pre = new int[graph.V()];

        Arrays.fill(visited, false);
        Arrays.fill(pre, -1);

        bfs(s);
    }

    private void bfs(int s) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(s);
        visited[s] = true;
        pre[s] = s;

        while (!queue.isEmpty()) {
            int v = queue.remove();
            for (int w: graph.adj(v)) {
                if (!visited[w]) {
                    queue.add(w);
                    visited[w] = true;
                    pre[w] = v;
                }
            }
        }
    }

    private void validate(int v) {
        if (v < 0 || v >= graph.V()) {
            throw new IllegalArgumentException("v is out of index");
        }
    }

    public boolean isConnected(int t) {
        validate(t);
        return visited[t];
    }

    public ArrayList<Integer> path(int t) {
        ArrayList<Integer> res = new ArrayList<>();
        if (!isConnected(t)) {
            return res;
        }

        int cur = t;
        while (cur != s) {
            res.add(cur);
            cur = pre[cur];
        }
        res.add(s);

        Collections.reverse(res);
        return res;
    }

    public static void main(String[] args) {
        Graph graph = new AdjSet("g4.txt");
        SingleSourcePath singleSourcePath = new SingleSourcePath(graph, 0);
        // 0 -> 6: [0, 2, 6]
        System.out.println("0 -> 6: " + singleSourcePath.path(6));
    }
}

import java.util.*;

public class SingleSourcePath {
    private Graph graph;
    private int s;

    private boolean[] visited;
    private int[] pre;
    // dis 数组保存源到各节点的距离
    private int[] dis;

    public SingleSourcePath(Graph graph, int s) {
        this.graph = graph;
        this.s = s;

        visited = new boolean[graph.V()];
        pre = new int[graph.V()];
        // 初始化
        dis = new int[graph.V()];

        Arrays.fill(visited, false);
        Arrays.fill(pre, -1);
        // 初始化
        Arrays.fill(dis, -1);

        bfs(s);
    }

    private void bfs(int s) {
        Queue<Integer> queue = new LinkedList<>();
        queue.add(s);
        visited[s] = true;
        pre[s] = s;
        // 源到源的距离为 0
        dis[s] = 0;

        while (!queue.isEmpty()) {
            int v = queue.remove();
            for (int w: graph.adj(v)) {
                if (!visited[w]) {
                    queue.add(w);
                    visited[w] = true;
                    pre[w] = v;
                    // 更新 dis
                    dis[w] = dis[v] + 1;
                }
            }
        }
    }

    // 与 path 相关代码省略
    public int dis(int t) {
        validate(t);
        return dis[t];
    }
}
